        if (ret !== 0 || q.isNull()) { outs.push([j, q.isNull() ? nrIt.outnull() : nrIt.ptr()]); return; }
        const iface = k[1] === ':' ? nrIfByName(k.slice(2)) : (nrIfByIid(n.riid[j]) || 1);
        outs.push([j, nrIt.obj(nrNewObj(q, iface, n.seq, 1, n.thr))]);
