// ---------------------------------------------------------------- DPLAYX exports (hooked when the module maps)
const NR_EX = NR_TABLES.exports;
const nrHooked = new Set();
function nrHookModule(m, thr) {
  const name = m.name.toLowerCase();
  if (!nrIsDpName(name) || nrHooked.has(name)) return;
  nrHooked.add(name);
  nrDpRanges.push([m.base, m.base.add(m.size)]);
  nrEmit(NR_T.MODULE, 1, nrP.module(nrPos(thr), thr, name));
  if (name !== 'dplayx.dll') return;
  NR_EX.forEach(([ex, , kinds], i) => {
    const addr = m.findExportByName(ex);
    if (!addr) return;
    const cs = ex.endsWith('W') ? 'W' : 'A';
    Interceptor.attach(addr, {
      onEnter(args) {
        this.nr = null;
        if (nrEnded || nrInternal(this.returnAddress)) return;
        nrEnter(this, args, 0, 0, i, 0xffffffff, kinds, cs, this.returnAddress, nrThr());
      },
      onLeave(rv) { nrLeave(this, rv); },
    });
  });
}

// ---------------------------------------------------------------- golf_clean.exe's LoadLibraryA / GetProcAddress slots
// (KERNEL32 IAT 0x004ba000: GetProcAddress 0x004ba0a4, LoadLibraryA 0x004ba0a8, from the import directory; their call
// sites 0x004a00aa / 0x004a00c0 load the display library, 0x00483fd1 the sound library, 0x004ac8ea / 0x004ac902 USER32 for
// the CRT's message box): only calls that name or return a DirectPlay module are logged
const NR_EXE_SLOTS = { GetProcAddress: 0x004ba0a4, LoadLibraryA: 0x004ba0a8 };
const NR_DPNAME_RE = /dplay|dpwsock|dpnet|dpmodem|dpvoice|dpserial/i;
const nrBase = (s) => String(s).split(/[\\/]/).pop().toLowerCase();
function nrWrapExeSlot(va, ret, argt, impl) {
  const slot = ptr(va);
  const orig = new NativeFunction(slot.readPointer(), ret, argt, 'stdcall');
  const cb = K(new NativeCallback(function (...a) {
    const r = orig(...a);
    if (!nrEnded) {
      try { impl(a, r, this.returnAddress); } catch (e) { send({ type: 'error', where: 'net import', msg: String(e) }); }
    }
    return r;
  }, ret, argt, 'stdcall'));
  Memory.protect(slot, 4, 'rw-');
  slot.writePointer(cb);
}
nrWrapExeSlot(NR_EXE_SLOTS.LoadLibraryA, 'pointer', ['pointer'], (a, r, ra) => {
  const nm = a[0].isNull() ? '' : a[0].readAnsiString();
  const dp = !r.isNull() && !!nrDpModuleAt(r);
  if (!dp && !NR_DPNAME_RE.test(nm)) return;
  const thr = nrThr();
  nrEmit(NR_T.LOADLIB, 0, nrP.loadlib(nrPos(thr), thr, trSite(ra.toUInt32()), dp ? 1 : 0, nrBase(nm)));
});
nrWrapExeSlot(NR_EXE_SLOTS.GetProcAddress, 'pointer', ['pointer', 'pointer'], (a, r, ra) => {
  const m = nrDpModuleAt(a[0]);
  if (!m) return;
  const byord = a[1].toUInt32() < 0x10000;
  const nm = byord ? '' : a[1].readAnsiString();
  let exp = r.isNull() ? 0xfe : 0xff;
  NR_EX.forEach(([ex], i) => {
    if (exp !== 0xff) return;
    const e = m.findExportByName(ex);
    if ((!byord && ex === nm) || (e && e.equals(r))) exp = i;
  });
  const thr = nrThr();
  nrEmit(NR_T.GETPROC, 0, nrP.getproc(nrPos(thr), thr, trSite(ra.toUInt32()), 1, byord ? 1 : 0,
                                      byord ? a[1].toUInt32() : 0, nm, exp));
});

// ---------------------------------------------------------------- watch: the exe's DirectPlay pointer (sidecar only)
// 0x008400b0 is read by the net layer (0x00497d62, 0x00497ffb, 0x0049b7b0 ...) and cleared at 0x00497d78; no instruction of
// golf_clean.exe or of the three game DLLs encodes a store of another value there (S9.2 notes, U-1760). A real-time poll
// reports the first change to Python: not a trace record, since its timing is the host's (net_recordings.md section 5).
{
  const watch = (NRC.watch || [0x008400b0]).map((va) => ({ va, last: ptr(va).readU32() }));
  const t = setInterval(() => {
    if (nrEnded) { clearInterval(t); return; }
    for (const w of watch) {
      const v = ptr(w.va).readU32();
      if (v === w.last) continue;
      const m = v ? Process.findModuleByAddress(ptr(v)) : null;
      send({ type: 'nrec_watch', va: w.va, nonzero: v !== 0, module: m ? m.name.toLowerCase() : null, pos: tn(),
             calls: nrCount.calls });
      w.last = v;
    }
  }, 50);
}

// ---------------------------------------------------------------- install
for (const m of Process.enumerateModules()) nrHookModule(m, 0);
Process.attachModuleObserver({ onAdded(m) {
  try { nrHookModule(m, nrThr()); } catch (e) { send({ type: 'error', where: 'net module ' + m.name, msg: String(e && e.stack || e) }); }
} });
send({ type: 'nrec_ready', exports: NR_EX.length, ifaces: NR_IF.length, cbs: NR_CB.length });
